import os
from typing import List, Dict, Any
from Validation.compilation_stage import CompilationStage
from Validation.static_analysis_stage import StaticAnalysisStage
from Validation.dynamic_analysis_stage import DynamicAnalysisStage
from Validation.formatting_stage import FormattingStage
from Validation.llm_metric_stage import LLMMetricStage
from config import HasaimConfiguration, iter_list, iter_multilist

class ValidationPipeline:
    """Pipeline for validating code files generated by the LLM"""

    def __init__(self, output_dir: str, source_dir: str, prompt: str = None):
        """
        Initialize the pipeline.

        Args:
            output_dir: directory to write output files to for various tools
                        (logs w/ captured `stdout` and `stderr` streams)
            source_dir: directory containing the code files generated by the LLM
        """
        self.output_dir = os.path.abspath(output_dir)

        # Create `logs/` subdirectory, to contain all log files
        self.logs_dir = os.path.join(self.output_dir, "logs/")
        os.makedirs(self.logs_dir, exist_ok=True)

        # Create `artifacts/` subdirectory to contain all generated artifacts
        self.artifacts_dir = os.path.join(self.output_dir, "artifacts/")
        os.makedirs(self.artifacts_dir, exist_ok=True)

        # Path to project directory
        self.source_dir = os.path.abspath(source_dir)

        self.config = HasaimConfiguration({
            "static_analyzer": iter_multilist(["clang-tidy", "cppcheck"], ["clang-tidy"]),
            "command_line_args": "",
            "tool": iter_multilist(["memcheck", "helgrind", "massif", "callgrind"], ["memcheck"]),
            "check_only": True,
            "style": iter_list(["LLVM", "Google"], 0)
        })

        # Pipeline stages
        self.compilation = CompilationStage(
            logs_dir=os.path.join(self.logs_dir, "compilation/"),
            artifacts_dir=os.path.join(self.artifacts_dir, "compilation/"),
            project_root=self.source_dir
        )
        self.static_analysis = StaticAnalysisStage(
            logs_dir=os.path.join(self.logs_dir, "static_analysis/"),
            artifacts_dir=os.path.join(self.artifacts_dir, "static_analysis/"),
            project_root=self.source_dir
        )
        self.dynamic_analysis = DynamicAnalysisStage(
            logs_dir=os.path.join(self.logs_dir, "dynamic_analysis/")
        )
        self.formatting_stage = FormattingStage(
            logs_dir=os.path.join(self.logs_dir, "formatting/"),
            artifacts_dir=os.path.join(self.artifacts_dir, "formatting/")
        )

        # To be implemented in future sprints
        # ====================================
        # self.unit_tester = UnitTestStage(output_dir)

        # self.llm = LLMMetricStage(
        #     output_dir=os.path.join(self.output_dir, "LLMMetrics/"),
        #     project_root=self.source_dir,
        #     prompt_text=prompt
        # )

    def run(self) -> Dict[str, Dict[str, Any]]:
        """
        Run the pipeline

        Returns:
            A dictionary mapping the name of validation stage to a
            collection of outputs associated with that stage:
                - success/failure of stage
                - generated errors/warnings
                - stdout/stderr
                - any misc. artifacts
        """
        results = {}

        # Containers to collect source code and header
        # files from LLM/output directory
        c_files, h_files, include_dirs = self._collect_file_paths()

        # Guard: require at least one .c file before attempting any stage
        if not c_files:
            print("[Validation] ERROR: No .c source files found — aborting pipeline.")
            return {
                "error_type": "no_c_files",
                "error_detail": (
                    "No .c source files were found in the project directory. "
                    "This tool currently supports C projects only. "
                    "Please upload at least one .c source file."
                )
            }

        # Stage 1: Compilation
        print("[Validation] Stage 1/4: Compiling project...")
        results["compilation"] = self.compilation.run()

        # Surface structured compilation errors (missing Makefile, unsupported compiler)
        error_type = results["compilation"].get("error_type")
        if error_type:
            detail = results["compilation"].get("error_detail", "")
            print(f"[Validation] Compilation ERROR ({error_type}): {detail}")
            return results

        status = "OK" if results["compilation"].get("executable_path") else "FAILED"
        print(f"[Validation] Compilation: {status}")

        # Stage 2: Static Analysis
        # `bear` deposits `compile_commands.json` in the project root
        print("[Validation] Stage 2/4: Running static analysis...")
        results["static_analysis"] = self.static_analysis.run(
            source_files=c_files,
            compile_commands=self.source_dir,
            static_analyzers=self.config.list_items("static_analyzer")
        )
        status = "OK" if results["static_analysis"].get("overall_success") else "FAILED"
        print(f"[Validation] Static analysis: {status}")

        # Stage 3: Dynamic Analysis
        print("[Validation] Stage 3/4: Running dynamic analysis...")
        exe_path = results["compilation"].get("executable_path")
        # GUARD: If compilation failed and no executable was produced, skip dynamic analysis stage
        if exe_path is None:
            results["dynamic_analysis"] = {
                "success": False,
                "reason": "Analysis was skipped since no valid executable was produced."
            }
            print("[Validation] Dynamic analysis: SKIPPED (no executable)")
        # Otherwise, run dynamic analysis as normal
        else:
            results["dynamic_analysis"] = self.dynamic_analysis.run(
                executable_path=exe_path,
                tools=self.config.list_items("tool"),
                flags=self.config["command_line_args"].split() if self.config["command_line_args"] else []
            )
            status = "OK" if results["dynamic_analysis"].get("overall_success") else "FAILED"
            print(f"[Validation] Dynamic analysis: {status}")

        # Stage 4: Formatting
        print("[Validation] Stage 4/4: Checking formatting...")
        results["formatting"] = self.formatting_stage.run(
            source_files=c_files,
            check_only=self.config["check_only"],
            style=self.config.list_item("style")
        )
        status = "OK" if results["formatting"].get("overall_success") else "FAILED"
        print(f"[Validation] Formatting: {status}")

        # Further steps to be implemented later...

        # results["LLMMetrics"] = self.llm.run()

        return results

    def _collect_file_paths(self) -> tuple[List[str], List[str], List[str]]:
        """
        Iterate thru LLM output directory and extract:
            - .c files
            - .h files
            - all include directories

        Returns:
            (c_files, h_files, include_dirs)
        """
        # Containers to store paths to files in source directory
        c_files = []
        h_files = []
        # Set to track all include directories
        include_dirs = set()

        # Traverse all file paths in source directory
        for root, dirs, files in os.walk(self.source_dir, topdown=True):
            # Append ABSOLUTE PATHS to all pertinent files
            for filename in files:
                if filename.endswith(".c"):
                    c_files.append(os.path.abspath(os.path.join(root, filename)))
                elif filename.endswith(".h"):
                    include_dirs.add(os.path.abspath(root))
                    h_files.append(os.path.abspath(os.path.join(root, filename)))

        return c_files, h_files, list(include_dirs)
